public:
    vector<int> minOperationsQueries(int n, vector<vector<int>>& edges, vector<vector<int>>& queries) {
        vector<vector<pair<int, int>>> adj(n);
        for (auto& e : edges) {
            adj[e[0]].push_back({e[1], e[2]});
            adj[e[1]].push_back({e[0], e[2]});
        }
        vector<int> depth(n, 0);
        vector<vector<int>> up(n, vector<int>(15, 0));
        vector<vector<int>> cnt(n, vector<int>(27, 0));
        vector<int> q = {0};
        vector<bool> vis(n, false);
        vis[0] = true;
        int head = 0;
        while (head < q.size()) {
            int u = q[head++];
            for (auto& edge : adj[u]) {
                int v = edge.first, w = edge.second;
                if (!vis[v]) {
                    vis[v] = true;
                    depth[v] = depth[u] + 1;
                    up[v][0] = u;
                    cnt[v] = cnt[u];
                    cnt[v][w]++;
                    q.push_back(v);
                }
            }
        }
        for (int j = 1; j < 15; j++) {
            for (int i = 0; i < n; i++) {
                up[i][j] = up[up[i][j - 1]][j - 1];
            }
        }
        auto get_lca = [&](int u, int v) {
            if (depth[u] < depth[v]) swap(u, v);
            int diff = depth[u] - depth[v];
            for (int i = 0; i < 15; i++) if ((diff >> i) & 1) u = up[u][i];
            if (u == v) return u;
            for (int i = 14; i >= 0; i--) {
                if (up[u][i] != up[v][i]) {
                    u = up[u][i];
                    v = up[v][i];
                }
            }
            return up[u][0];
        };
        vector<int> ans;
        ans.reserve(queries.size());
        for (auto& qry : queries) {
            int u = qry[0], v = qry[1];
            int lca = get_lca(u, v);
            int path_len = depth[u] + depth[v] - 2 * depth[lca];
            int max_freq = 0;
            for (int w = 1; w <= 26; w++) {
                int c = cnt[u][w] + cnt[v][w] - 2 * cnt[lca][w];
                max_freq = max(max_freq, c);
            }
            ans.push_back(path_len - max_freq);
        }
        return ans;
    }
};

class Solution {
    public int[] minOperationsQueries(int n, int[][] edges, int[][] queries) {
        List<int[]>[] adj = new ArrayList[n];
        for (int i = 0; i < n; i++) adj[i] = new ArrayList<>();
        for (int[] e : edges) {
            adj[e[0]].add(new int[]{e[1], e[2]});
            adj[e[1]].add(new int[]{e[0], e[2]});
        }
        int[] depth = new int[n];
        int[][] up = new int[n][15];
        int[][] cnt = new int[n][27];
        boolean[] vis = new boolean[n];
        Queue<Integer> q = new LinkedList<>();
        q.add(0);
        vis[0] = true;
        while (!q.isEmpty()) {
            int u = q.poll();
            for (int[] edge : adj[u]) {
                int v = edge[0], w = edge[1];
                if (!vis[v]) {
                    vis[v] = true;
                    depth[v] = depth[u] + 1;
                    up[v][0] = u;
                    System.arraycopy(cnt[u], 0, cnt[v], 0, 27);
                    cnt[v][w]++;
                    q.add(v);
                }
            }
        }
        for (int j = 1; j < 15; j++) {
            for (int i = 0; i < n; i++) {
                up[i][j] = up[up[i][j - 1]][j - 1];
            }
        }
        int[] ans = new int[queries.length];
        for (int qi = 0; qi < queries.length; qi++) {
            int u = queries[qi][0], v = queries[qi][1];
            int lca = getLca(u, v, depth, up);
            int pathLen = depth[u] + depth[v] - 2 * depth[lca];
            int maxFreq = 0;
            for (int w = 1; w <= 26; w++) {
                int c = cnt[u][w] + cnt[v][w] - 2 * cnt[lca][w];
                maxFreq = Math.max(maxFreq, c);
            }
            ans[qi] = pathLen - maxFreq;
        }
        return ans;
    }
    private int getLca(int u, int v, int[] depth, int[][] up) {
        if (depth[u] < depth[v]) { int t = u; u = v; v = t; }
        int diff = depth[u] - depth[v];
        for (int i = 0; i < 15; i++) if (((diff >> i) & 1) == 1) u = up[u][i];
        if (u == v) return u;
        for (int i = 14; i >= 0; i--) {
            if (up[u][i] != up[v][i]) {
                u = up[u][i];
                v = up[v][i];
            }
        }
        return up[u][0];
    }
}

