var minOperationsQueries = function(n, edges, queries) {
    const adj = Array.from({ length: n }, () => []);
    for (const [u, v, w] of edges) {
        adj[u].push([v, w]);
        adj[v].push([u, w]);
    }
    const depth = new Int32Array(n);
    const up = Array.from({ length: n }, () => new Int32Array(15));
    const cnt = Array.from({ length: n }, () => new Int32Array(27));
    const q = [0];
    const vis = new Uint8Array(n);
    vis[0] = 1;
    let head = 0;
    while (head < q.length) {
        const u = q[head++];
        for (const [v, w] of adj[u]) {
            if (!vis[v]) {
                vis[v] = 1;
                depth[v] = depth[u] + 1;
                up[v][0] = u;
                cnt[v].set(cnt[u]);
                cnt[v][w]++;
                q.push(v);
            }
        }
    }
    for (let j = 1; j < 15; j++) {
        for (let i = 0; i < n; i++) {
            up[i][j] = up[up[i][j - 1]][j - 1];
        }
    }
    const getLca = (u, v) => {
        if (depth[u] < depth[v]) { const t = u; u = v; v = t; }
        const diff = depth[u] - depth[v];
        for (let i = 0; i < 15; i++) if ((diff >> i) & 1) u = up[u][i];
        if (u === v) return u;
        for (let i = 14; i >= 0; i--) {
            if (up[u][i] !== up[v][i]) {
                u = up[u][i];
                v = up[v][i];
            }
        }
        return up[u][0];
    };
    const ans = [];
    for (const [u, v] of queries) {
        const lca = getLca(u, v);
        const pathLen = depth[u] + depth[v] - 2 * depth[lca];
        let maxFreq = 0;
        for (let w = 1; w <= 26; w++) {
            const c = cnt[u][w] + cnt[v][w] - 2 * cnt[lca][w];
            if (c > maxFreq) maxFreq = c;
        }
        ans.push(pathLen - maxFreq);
    }
    return ans;
};
